# ---------- US 1099 / self-employment tax ----------
sfaq=[("How much is self-employment tax in 2026?","15.3% of 92.35% of your net profit: 12.4% Social Security on the first $184,500 of combined wages and self-employment earnings, plus 2.9% Medicare on everything (no cap). So $100,000 of profit has $92,350 of earnings and $14,129.55 of self-employment tax. If you owe less than $400 of net earnings, you do not owe it."),
("Do I pay self-employment tax on 1099 income if I also have a W-2 job?","Yes, on the 1099 profit. But Social Security tax is capped at $184,500 of wages plus self-employment earnings combined, so W-2 wages use up part of the cap first; this calculator subtracts your W-2 Social Security wages before applying the 12.4%. Medicare tax is not capped."),
("What is the Additional Medicare Tax and does it apply to me?","An extra 0.9% on Medicare wages and self-employment earnings above $200,000 (single or head of household) or $250,000 (married filing jointly), reported on Form 8959. It is included in the total above. This tool uses only your own wages, so a married couple whose combined wages are high should add the Form 8959 worksheet result."),
("How is the quarterly estimated tax payment worked out?","Form 1040-ES uses the smaller of 90% of your expected 2026 total tax (income tax plus self-employment tax) or 100% of your 2025 tax (110% if your 2025 AGI was over $150,000). Subtract income tax withheld from any job, and divide by four. You do not have to pay if you expect to owe under $1,000 after withholding."),
("What are the 2026 estimated tax due dates?","April 15, 2026, June 15, 2026, September 15, 2026 and January 15, 2027. You can skip the January 15, 2027 payment if you file your 2026 return by February 1, 2027 and pay the full balance with it."),
("What is the QBI deduction and how big is it here?","The qualified business income deduction lets most sole proprietors deduct up to 20% of qualified business income, limited to 20% of taxable income before it. Above $201,750 of taxable income (single or head of household) or $403,500 (joint) it phases out over $75,000 / $150,000 for a business with no W-2 employees, which is how this calculator treats it. For 2026 there is also a $400 minimum deduction if you have at least $1,000 of qualified business income."),
("What if I earned money but did not get a 1099?","It is still taxable. The 1099-NEC/1099-MISC reporting threshold only decides whether a client has to send you a form (it rises from $600 to $2,000 for payments made in 2026); you report all net business income on Schedule C."),
("Does this include state income tax?","No. This is federal only. Nine states, including Texas, Florida and Washington (wages), have no tax on wage income, but most states do tax self-employment profit; add your state's tax on top of the total here."),
("What is not included in this estimate?","Credits (child tax credit, education credits), itemized deductions, capital gains and qualified dividends, net investment income tax, the new tips, overtime, senior and car-loan deductions, alternative minimum tax and state taxes. For a sole proprietor with no employees and no significant business property only.")]
sfaq[7]=("Does this include state income tax?","No. This is federal only. Some states, such as Texas, Florida, Nevada and Washington, have no tax on personal income, but most states do tax self-employment profit; add your state's tax on top of the total here.")
sfaq[8]=("What is not included in this estimate?","Credits (child tax credit, education credits), itemized deductions, capital gains and qualified dividends, net investment income tax, the new tips, overtime, senior and car-loan deductions, alternative minimum tax and state taxes. The QBI deduction is modeled for a sole proprietor with no employees and no business property, and is not adjusted for specified service trades.")
body=f'''<h1>1099 Self-Employment Tax Calculator 2026, with Quarterly Estimated Payments</h1>
<p class="lede">Enter your 1099 income and expenses to see your 2026 federal self-employment tax, your income tax after the 20% QBI deduction, how much of each payment to set aside, and the quarterly amount IRS Form 1040-ES says to pay to stay clear of the underpayment penalty. It runs in your browser and follows the IRS's own estimated-tax worksheet.</p>
<div class="card"><div class="grid">
<div><label for="st">Filing status</label><select id="st"><option value="single">Single</option><option value="mfj">Married filing jointly</option><option value="hoh">Head of household</option></select></div>
<div><label for="rev">2026 1099 income <span class="hint">(all clients, before expenses)</span></label><input id="rev" inputmode="decimal" placeholder="90000"></div>
<div><label for="exp">Business expenses</label><input id="exp" inputmode="decimal" placeholder="10000"></div>
<div><label for="wg">Your own W-2 wages <span class="hint">(if any; box 3 or 5)</span></label><input id="wg" inputmode="decimal"></div>
<div><label for="ot">Other taxable income <span class="hint">(spouse's wages, interest, etc.)</span></label><input id="ot" inputmode="decimal"></div>
<div><label for="bd">Self-employed health insurance, SEP or solo 401(k)</label><input id="bd" inputmode="decimal"></div>
<div><label for="ad">Other adjustments <span class="hint">(IRA, student loan interest, HSA)</span></label><input id="ad" inputmode="decimal"></div>
<div><label for="wh">Income tax withheld from your W-2 pay</label><input id="wh" inputmode="decimal"></div>
<div><label for="pp">2026 estimated payments already made</label><input id="pp" inputmode="decimal"></div>
<div><label for="pt">2025 total tax <span class="hint">(optional, for the safe harbor)</span></label><input id="pt" inputmode="decimal"></div>
<div><label for="pa">2025 adjusted gross income <span class="hint">(optional)</span></label><input id="pa" inputmode="decimal"></div></div>
<button id="go">Calculate my 2026 self-employment tax</button></div>
<div id="out" class="card result" hidden></div>
<p>Employed instead of self-employed? Try the <a href="/texas-paycheck-calculator/">Texas paycheck calculator</a> (hourly, overtime and bonus). Freelancing in Canada? See the <a href="/self-employed-tax-calculator/">Canadian self-employed tax calculator</a>.</p>
<h2>How this 2026 calculation works</h2>
<p>It mirrors the steps of the IRS's own Form 1040-ES worksheets: (1) self-employment earnings = net profit × 92.35%; (2) Social Security 12.4% on earnings up to the $184,500 wage base minus your W-2 wages, plus Medicare 2.9%; (3) half of that tax is deducted from income; (4) standard deduction ($16,100 single, $32,200 joint, $24,150 head of household); (5) the QBI deduction; (6) tax from the 2026 brackets (10% to 37%); (7) the Additional Medicare Tax if your earnings are high; (8) required annual payment = the smaller of 90% of the 2026 total or 100% (110%) of the 2025 tax, minus withholding, split in four.</p>
<div class="scroll"><table><thead><tr><th>2026 figure</th><th>Amount</th></tr></thead><tbody><tr><td>Self-employment tax rate</td><td>15.3% (12.4% + 2.9%) on 92.35% of profit</td></tr><tr><td>Social Security wage base</td><td>$184,500</td></tr><tr><td>Additional Medicare Tax</td><td>0.9% over $200,000 single / $250,000 joint</td></tr><tr><td>Standard deduction</td><td>$16,100 single · $32,200 joint · $24,150 head of household</td></tr><tr><td>Top of the 10% / 12% / 22% / 24% brackets (single)</td><td>$12,400 / $50,400 / $105,700 / $201,775</td></tr><tr><td>QBI phase-out begins</td><td>$201,750 single · $403,500 joint</td></tr><tr><td>Estimated tax due dates</td><td>Apr 15, Jun 15, Sep 15, 2026 · Jan 15, 2027</td></tr></tbody></table></div>
{faqhtml(sfaq)}
{src(US_SRC)}
<p class="disc">Not tax advice. Estimate of federal tax for 2026 using IRS figures published as of October 25, 2026, for a sole proprietor with no employees, filing single, head of household or married filing jointly, taking the standard deduction. Excludes state tax, credits, capital gains, itemized deductions, the net investment income tax and the new tips, overtime, senior and car-loan deductions. Additional Medicare Tax is based on your own wages only. The IRS and a tax professional are the authority for your own situation.</p>'''
UJ=dict(bad="Enter your 1099 income and expenses (profit must be positive).")
js='<script>'+FMT+money_en+f'const J={json.dumps(UJ)};'+'''const D=[["April 15, 2026",new Date(2026,3,15)],["June 15, 2026",new Date(2026,5,15)],["September 15, 2026",new Date(2026,8,15)],["January 15, 2027",new Date(2027,0,15)]];
$("go").onclick=()=>{const o=$("out");o.hidden=false;const profit=v("rev")-v("exp");
if(!(profit>0)){o.innerHTML="<p class=bad>"+J.bad+"</p>";return;}
const pt=$("pt").value.trim()===""?null:v("pt"),r=NLUS.estimate({status:$("st").value,profit:profit,wages:v("wg"),other:v("ot"),bizDed:v("bd"),adj:v("ad"),withheld:v("wh"),prepaid:v("pp"),priorTax:pt,priorAgi:v("pa")});
const now=new Date(),rows=D.map(d=>`<tr><td>${d[0]}</td><td>${d[1]<new Date(now.getFullYear(),now.getMonth(),now.getDate())?"passed":"upcoming"}</td></tr>`).join("");
let h=`<p>Set aside from each 1099 payment</p><p class=big>${(100*r.setAsidePct).toFixed(1)}%</p><p class=hint>That is ${f(1000*r.setAsidePct)} from every $1,000 of profit (federal only; add your state tax).</p>`;
h+="<table><tbody>"+[["Net profit",profit],["Self-employment tax (Social Security "+f(r.ss)+" + Medicare "+f(r.med)+")",r.tax],["Additional Medicare Tax (Form 8959)",r.addl],["Deduction: half of self-employment tax",-r.half],["Adjusted gross income",r.agi],["Taxable income before QBI deduction",r.tiPre],["QBI deduction (20%)",-r.qbid],["Taxable income",r.ti],["Income tax (2026 brackets)",r.inc],["Total 2026 federal tax",r.total],["Less income tax withheld",-r.withheld],["Less estimated payments already made",-r.prepaid],["Balance due at filing (approx.)",r.balance]].map(x=>`<tr><td>${x[0]}</td><td>${f(x[1])}</td></tr>`).join("")+"</tbody></table>";
if(r.payRequired){h+=`<p><b>Estimated tax payments are required.</b> Required annual payment (${r.priorReq!=null&&r.priorReq<r.ninety?"based on your 2025 tax"+(r.pctPrior>1?" at 110%":""):"90% of your 2026 tax"}): <b>${f(r.required)}</b>, less ${f(r.withheld)} withheld = ${f(r.afterW)}. Each of four equal payments: <b>${f(r.perQuarter)}</b>.</p>`;
 if(r.prepaid>0)h+=`<p class=hint>Still to pay toward that required amount: ${f(r.remaining)}.</p>`;
 h+="<div class=scroll><table><thead><tr><th>Due date</th><th>Status</th></tr></thead><tbody>"+rows+"</tbody></table></div><p class=hint>If you have missed earlier dates, pay what is still needed as soon as you can: the penalty is calculated by payment period. You can skip the January 15, 2027 payment if you file by February 1, 2027 and pay the whole balance.</p>";}
else h+=`<p><b>Estimated tax payments are probably not required</b> (you expect to owe under $1,000 after withholding, or your withholding covers the safe harbor). You will still owe the balance when you file.</p>`;
o.innerHTML=h;o.scrollIntoView({behavior:"smooth"});};</script>'''
