tfaq=[("Does Texas have a state income tax on paychecks?","No. Article VIII, Section 24-a of the Texas Constitution says the legislature may not tax the net incomes of individuals, so no Texas income tax is withheld from your pay. Federal income tax, Social Security and Medicare still come out. Texas does charge sales and property taxes, which are not taken from paychecks."),
("What comes out of a Texas paycheck in 2026?","Federal income tax withholding (from your Form W-4 and the IRS Pub. 15-T tables), Social Security at 6.2% of wages up to $184,500 for the year, Medicare at 1.45% of all wages (plus 0.9% on wages above $200,000), and any pre-tax benefits you elect such as a 401(k) or health insurance. Texas unemployment tax is paid by the employer only."),
("How is overtime pay taxed in Texas?","Overtime is regular wages: withheld the same way, annualized by your payroll system. Because a big overtime check is annualized, it can look like a higher bracket, but your actual tax is settled on your return. Federal law requires time-and-a-half over 40 hours in a workweek for covered non-exempt employees, which applies to most private employers in Texas; this calculator uses 1.5 times your hourly rate."),
("Is there a tax deduction for overtime in 2026?","Yes, a new federal one. From 2025 through 2028 you can deduct the premium portion of FLSA-required overtime (the 'half' in time-and-a-half), up to $12,500 ($25,000 joint), phasing out above $150,000 of income ($300,000 joint). It is claimed on your return, so it does not change your paycheck withholding by itself; the estimate on this page shows what it could be worth."),
("How is a bonus taxed?","If your employer pays it separately from regular wages, federal income tax is withheld at a flat 22% (37% over $1 million of supplemental wages in a year), plus 7.65% Social Security and Medicare. In Texas there is no state tax on it. If it is paid together with regular wages, the employer may instead add it to the paycheck and use the regular tables."),
("How often must employers in Texas pay?","Employees who are not exempt from overtime must be paid at least twice a month, and exempt employees at least once a month, on paydays the employer designates (Texas Labor Code 61.011). Someone fired must be paid within six days; someone who quits by the next regular payday (61.014)."),
("What is the Texas minimum wage in 2026?","$7.25 an hour, the federal minimum: Texas adopts it and does not set its own. A full-time worker at that rate earns $290 a week before tax."),
("Why is my paycheck different from this estimate?","Your employer's payroll system may round, use the wage-bracket tables, handle bonuses differently, or apply a different W-4 entry. Pre-tax and post-tax deductions, garnishments, union dues, tips and fringe benefits are not all modeled here. Treat it as an estimate and check your pay stub."),
("Should I change my W-4 if my paycheck is too small or large?","If you want a different amount withheld, adjust your Form W-4 (extra withholding in Step 4(c), or credits and deductions in Steps 3 and 4(b)). The IRS Tax Withholding Estimator is the official tool for that.")]
body=f'''<h1>Texas Paycheck Calculator 2026: Hourly, Overtime and Bonus</h1>
<p class="lede">Find your take-home pay in Texas for 2026: federal income tax from the IRS's own Pub. 15-T tables, Social Security and Medicare, 401(k) and health deductions, and no Texas income tax. Add overtime hours to see the pay and the new federal overtime deduction, or a bonus to see its flat 22% withholding.</p>
<div class="card"><div class="grid">
<div><label for="md">Paid</label><select id="md"><option value="hourly">Hourly</option><option value="salary">Salary</option></select></div>
<div><label for="pf">Pay frequency</label><select id="pf"><option value="52">Weekly</option><option value="26" selected>Every two weeks</option><option value="24">Twice a month</option><option value="12">Monthly</option></select></div>
<div id="g1"><label for="rt">Hourly rate</label><input id="rt" inputmode="decimal" placeholder="22.50"></div>
<div id="g2"><label for="hr">Regular hours this paycheck</label><input id="hr" inputmode="decimal" placeholder="80"></div>
<div id="g3"><label for="oh">Overtime hours this paycheck <span class="hint">(paid at 1.5×)</span></label><input id="oh" inputmode="decimal" placeholder="0"></div>
<div id="g4" hidden><label for="sl">Annual salary</label><input id="sl" inputmode="decimal" placeholder="65000"></div>
<div><label for="fs">Filing status on your W-4</label><select id="fs"><option value="single">Single or married filing separately</option><option value="mfj">Married filing jointly</option><option value="hoh">Head of household</option></select></div>
<div><label for="k4">401(k) / pre-tax retirement per paycheck</label><input id="k4" inputmode="decimal"></div>
<div><label for="s1">Pre-tax health, dental (Section 125) per paycheck</label><input id="s1" inputmode="decimal"></div>
<div><label for="bn">Bonus <span class="hint">(paid separately; optional)</span></label><input id="bn" inputmode="decimal"></div></div>
<details><summary>Form W-4 details (optional)</summary><div class="grid">
<div><label for="s2">Step 2 box checked (two jobs)?</label><select id="s2"><option value="0">No</option><option value="1">Yes</option></select></div>
<div><label for="s3">Step 3: credits (annual $, e.g. children)</label><input id="s3" inputmode="decimal"></div>
<div><label for="s4a">Step 4(a): other income (annual $)</label><input id="s4a" inputmode="decimal"></div>
<div><label for="s4b">Step 4(b): deductions (annual $)</label><input id="s4b" inputmode="decimal"></div>
<div><label for="s4c">Step 4(c): extra withholding per paycheck</label><input id="s4c" inputmode="decimal"></div></div></details>
<button id="go">Calculate my Texas paycheck</button></div>
<div id="out" class="card result" hidden></div>
<h2>What comes out of a Texas paycheck</h2>
<div class="scroll"><table><thead><tr><th>Item</th><th>2026 rule</th></tr></thead><tbody><tr><td>Texas income tax</td><td>None (Texas Constitution art. VIII, sec. 24-a)</td></tr><tr><td>Federal income tax</td><td>Per your W-4 and the Pub. 15-T percentage-method tables</td></tr><tr><td>Social Security</td><td>6.2% of wages up to $184,500 for the year</td></tr><tr><td>Medicare</td><td>1.45% of all wages; +0.9% on wages over $200,000</td></tr><tr><td>Texas unemployment tax</td><td>Employer pays it; employees cannot be charged</td></tr><tr><td>Minimum wage</td><td>$7.25 an hour (federal rate)</td></tr><tr><td>Supplemental wages (bonus)</td><td>22% flat federal withholding, 37% over $1 million</td></tr></tbody></table></div>
<p>Working in a state that does tax wages? See how California changes the picture with the <a href="/california-paycheck-calculator/">California paycheck calculator</a> (state withholding, SDI and daily overtime).</p>
<h2>Overtime in Texas: the pay and the new deduction</h2>
<p>Overtime for covered non-exempt employees is time-and-a-half over 40 hours in a workweek under the federal Fair Labor Standards Act, the rule that applies to most private employers in Texas. From 2025 through 2028 the extra half-time portion can be deducted from federal taxable income, up to $12,500 ($25,000 joint), if your income is under $150,000 ($300,000 joint). The deduction is taken on your tax return, so it shows up as a smaller tax bill or larger refund rather than a bigger paycheck, unless you account for it on your Form W-4. Enter your overtime hours above for an estimate of its value.</p>
{faqhtml(tfaq)}
{src(TX_SRC)}
<p class="disc">Not tax advice or payroll advice. Estimate of 2026 federal withholding using the IRS Pub. 15-T (2026) percentage method for an employee with one job and a Form W-4 from 2020 or later, as of October 25, 2026. It does not model post-tax deductions, garnishments, tips, fringe benefits, withholding above the Social Security wage base later in the year, or the 0.9% Additional Medicare Tax withholding above $200,000. The overtime deduction estimate assumes every paycheck looks like this one and is not a tax return calculation. Your employer's pay stub is the official figure.</p>'''
TJ=dict(bad="Enter your pay details first.")
js='<script>'+FMT+money_en+f'const J={json.dumps(TJ)};'+'''const md=$("md");md.onchange=()=>{const h=md.value==="salary";$("g1").hidden=$("g2").hidden=$("g3").hidden=h;$("g4").hidden=!h;};
$("go").onclick=()=>{const o=$("out");o.hidden=false;const h=md.value==="salary";
const inp={mode:md.value,rate:v("rt"),hours:v("hr"),otHours:v("oh"),salary:v("sl"),periods:parseInt($("pf").value),status:$("fs").value,step2:$("s2").value==="1",credits:v("s3"),otherInc:v("s4a"),deductions:v("s4b"),extra:v("s4c"),k401:v("k4"),s125:v("s1"),bonus:v("bn")};
if(!((h&&inp.salary>0)||(!h&&inp.rate>0&&(inp.hours>0||inp.otHours>0)))){o.innerHTML="<p class=bad>"+J.bad+"</p>";return;}
const r=NLUS.paycheck(inp),n=v("bn");
let t=`<p>Take-home pay per paycheck</p><p class=big>${f(r.net)}</p><p class=hint>${(100*r.takeHomePct).toFixed(1)}% of your ${f(r.gross)} gross pay. About ${f(r.annNet)} a year if every paycheck matched this one.</p>`;
t+="<table><tbody>"+[["Gross pay"+(r.ot>0?" (includes "+f(r.ot)+" overtime)":""),r.gross],["Federal income tax",-r.fed],["Social Security (6.2%)",-r.ss],["Medicare (1.45%)",-r.med],["Texas income tax",0],["401(k) / pre-tax retirement",-r.k401],["Pre-tax health (Section 125)",-r.s125],["Take-home pay",r.net]].map(x=>`<tr><td>${x[0]}</td><td>${f(x[1])}</td></tr>`).join("")+"</tbody></table>";
if(n>0)t+=`<h3>Bonus of ${f(n)}, paid separately</h3><p>Federal income tax at the flat 22%: ${f(r.bonusFed)}. Social Security and Medicare (7.65%): ${f(r.bonusFica)}. Texas tax: $0.00. <b>You keep ${f(r.bonusNet)}.</b></p>`;
if(r.otPrem>0){t+=`<h3>Qualified overtime deduction (estimate)</h3><p>If every paycheck had this much overtime, the overtime premium (the half in time-and-a-half) would be about ${f(r.otPrem)} a year; the deduction is capped at ${f(r.otDed)}.`;
 t+=r.otPhase?` Your annual income looks above the $150,000 / $300,000 level where the deduction starts to phase out, so the value would be reduced.`:` Claimed on your tax return, it could lower your federal income tax by about <b>${f(r.otSaving)}</b>. It does not change your paycheck withholding by itself.`;t+="</p>";}
o.innerHTML=t;o.scrollIntoView({behavior:"smooth"});};</script>'''
page("texas-paycheck-calculator/","Texas Paycheck Calculator 2026: Hourly, Overtime & Bonus | NorthLedger Tools",
 "Free 2026 Texas paycheck calculator: take-home pay from hourly or salary, overtime, 401(k) and bonus, using IRS Pub. 15-T withholding. Texas has no state income tax.",
 body,loc="en-US",ld=[app_ld("Texas Paycheck Calculator 2026",BASE+"texas-paycheck-calculator/","Calculates 2026 take-home pay in Texas from hourly or salary pay, overtime, pre-tax deductions and bonuses using IRS Pub. 15-T.",lang="en-US",cur="USD"),faq_ld(tfaq)],
 libs='<script src="/assets/us.js"></script>',script=js,upd=NEWUPD)
